import re

def remove_parenthesis(items):
    if isinstance(items, str):
        return re.sub(r'\([^)]*\)', '', items)
    return re.sub(r'\([^)]*\)', '', items[0]) if len(items) == 1 else [re.sub(r'\([^)]*\)', '', item) for item in items]

